mapper.update:
UPDATE notification
SET status = #{status}
WHERE notification_id = #{notificationId}

UPDATE notification
SET read_at = now()
WHERE notification_id = #{notificationId}
  AND account_id = #{accountId}

mapper.select:
SELECT FROM notification WHERE account_id = #{accountId} AND channel IN ('PUSH', 'BOTH')
AND read_at IS NULL
ORDER BY created_at DESC, notification_id DESC LIMIT #{limit}
